fn solve(input: Vec<char>) -> Vec<char> {
    // Mapping from digit character to the "good count"
    fn good_count(d: char) -> u32 {
        match d {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // theoretically unreachable given the problem statement
        }
    }
    
    // Extract first two characters (guaranteed at least length 2)
    let d1 = input[0];
    let d2 = input[1];
    
    let product = good_count(d1) * good_count(d2); // product in range 1..=49
    
    // Convert product to string representation with no leading zeros
    // (product is always positive, so direct conversion is fine)
    let mut output = product.to_string().chars().collect::<Vec<char>>();
    
    // Append newline character
    output.push('\n');
    
    output
}